interface Person {
  id: number;
  name: string;
  /** Every grade recorded for the person, the one from the beginning of time first. */
  protected readonly watched = signal<ReadonlySet<number>>(new Set());
  /** The error of each person's last refused row action, by person id. */
  protected readonly rowErrors = signal<ReadonlyMap<number, string>>(new Map());
  /** Each grade's rate in force on the sheet's today. */
  protected readonly pctOf = computed(() => {
    const today = this.session.figureDay();
    return new Map<string, string | undefined>(this.session.grades().map((g) => [g, pctOn(this.rates(), g, today)]));
  });
  /** The sheet's due-total: people's due-totals added up (skipping n/a), trimmed. */
  protected readonly dueTotal = computed(() =>
    money(trimmedSum(this.people().map((p) => this.dueOf(p)).filter((d): d is number => d !== null))),
  );
  /** The sheet's settled-total and open-total: everyone's added up, untrimmed, in whole cents. */
  protected readonly settledOpenTotals = computed(() => {
    const each = this.people().map((p) => this.settledOpenOf(p));
    return {
      settled: each.reduce((sum, t) => sum + t.settled, 0),
      open: each.reduce((sum, t) => sum + t.open, 0),
    };
  });
  protected readonly dueText = dueText;
  protected readonly money = money;
  protected readonly cents = cents;
  /** The figures of the sheet's descendants as the store holds them, added to its own for the consolidated figures. */
  protected readonly descendants = signal<Descendants>(NO_DESCENDANTS);
  /**
   * The figures over the sheet and its descendants. An as-of view shows every sheet of the tree as it
   * stood at the end of that day, adding the sheet's own figures as the store held them then; else the screen's own.
   */
  protected readonly consolidated = computed(() => {
    const d = this.descendants();
    const asOfOwn = this.session.asOf() ? d.own : null;
    const own = asOfOwn
      ? {
          people: asOfOwn.people.map((p) => ({
            names: p.names,
            due: p.dueTotal === null ? null : cents(p.dueTotal),
            overdue: cents(p.overdueTotal),
          })),
          grade: (g: string) => cents(asOfOwn.gradeDueTotals[g] ?? '0.00'),
          status: (s: string) => asOfOwn.statusCounts[s] ?? 0,
        }
      : {
          people: this.people().map((p) => ({
            names: [p.name, ...p.aliases],
            due: this.dueOf(p),
            overdue: this.overdueOf(p).cents,
          })),
          grade: (g: string) => cents(this.gradeSummary().find((x) => x.grade === g)?.dueTotal ?? '0.00'),
          status: (s: string) => this.statusCount(s),
        };
    // the trim and the people count run once over every person of the tree
    const tree = [
      ...own.people,
      ...d.people.map((p) => ({
        names: p.names,
        due: p.dueTotal === null ? null : cents(p.dueTotal),
        overdue: cents(p.overdueTotal),
      })),
    ];
    return {
      peopleCount: distinctPeople(tree.map((p) => p.names)),
      dueTotal: money(trimmedSum(tree.map((p) => p.due).filter((d): d is number => d !== null))),
      overdueTotal: money(trimmedSum(tree.map((p) => p.overdue))),
      grades: [...new Set([...this.session.grades(), ...Object.keys(d.gradeDueTotals)])].sort().map((grade) => ({
        grade,
        dueTotal: money(own.grade(grade) + cents(d.gradeDueTotals[grade] ?? '0.00')),
      })),
      statuses: SUMMARY_STATUSES.map((status) => ({
        status,
        count: own.status(status) + (d.statusCounts[status] ?? 0),
      })),
    };
  });
  /** How many claims of the sheet and its descendants are in a status, as the consolidated figures count them. */
  protected treeStatusCount(status: string): number {
    return this.consolidated().statuses.find((s) => s.status === status)?.count ?? 0;
  }
  /** How many overdue claims that count the sheet and its descendants have (the sheet's own as of the date, in an as-of view). */
  protected readonly treeOverdueCount = computed(() => {
    const d = this.descendants();
    const own = this.session.asOf() && d.own ? d.own.overdueCount : this.overdueTotals().count;
    return own + d.overdueCount;
  });
  /** The person on the sheet with the user's name, by name or alias (compared without regard to case). */
  private readonly me = computed(() => {
    const user = this.session.user()?.toLowerCase();
    if (!user) return undefined;
    return this.people().find(
      (p) => p.name.toLowerCase() === user || p.aliases.some((a) => a.toLowerCase() === user),
    );
  });
  /** The people this screen added since the sheet was last loaded: a restricted user sees them until the next load. */
  private readonly addedHere = signal<ReadonlySet<number>>(new Set());
  /** The signed-in user's role on the sheet, as last read from the store. */
  private readonly role = signal('');
  /**
   * The ids of the people a restricted user may see on the list: the person with the user's name
   * and everyone in the crews they lead or belong to; null for any other role, who sees everyone.
   * Only the rows shown are narrowed: every total and figure stays over everyone on the sheet.
   */
  private readonly seenIds = computed<ReadonlySet<number> | null>(() => {
    if (this.role() !== 'restricted') return null;
    const me = this.me();
    const seen = new Set<number>();
    if (!me) return seen;
    seen.add(me.id);
    for (const c of this.crews()) {
      if (c.leadId !== me.id && !c.members.some((m) => m.personId === me.id)) continue;
      if (c.leadId !== null) seen.add(c.leadId);
      for (const m of c.members) seen.add(m.personId);
    }
    return seen;
  });
  /** The due-totals of the crews the user's person leads, added up; blank when they lead none. */
  protected readonly myCrewDueTotal = computed(() => {
    const me = this.me();
    const led = me ? this.crews().filter((c) => c.leadId === me.id) : [];
    if (led.length === 0) return '';
    const people = this.crewPeople();
    return money(led.reduce((sum, c) => sum + crewDueCents(c, people), 0));
  });
  /** The due-totals of the people the user watches, added up (skipping n/a); 0.00 when they watch no one. */
  protected readonly watchedDueTotal = computed(() => {
    const watched = this.watched();
    return money(this.people().filter((p) => watched.has(p.id)).reduce((sum, p) => sum + (this.dueOf(p) ?? 0), 0));
  });
  /**
   * The signed-in user's own figures: the due- and overdue-totals of the person on the sheet with
   * the user's name, by name or alias (compared without regard to case); none when there is no such person.
   */
  protected readonly myFigures = computed(() => {
    const me = this.me();
    return me ? { dueTotal: dueText(this.dueOf(me)), overdueTotal: money(this.overdueOf(me).cents) } : null;
  });
  /** The sheet's OPEN and PENDING claims that count, in whole cents by age: the people's buckets added up, untrimmed. */
  protected readonly agedTotals = computed(() =>
    this.people().map((p) => this.agedOf(p)).reduce<[number, number, number]>(
      (sum, a) => [sum[0] + a[0], sum[1] + a[1], sum[2] + a[2]],
      [0, 0, 0],
    ),
      const key = name.toLowerCase();
      const other = owner.get(key);
      if (other === undefined) owner.set(key, i);
      else parent[root(i)] = root(other);
    }
  });
  return parent.filter((_, i) => root(i) === i).length;
}

function trimmedSum(figures: readonly number[]): number {
  const sum = figures.reduce((s, f) => s + f, 0);
  return figures.length < 3 ? sum : sum - Math.max(...figures) - Math.min(...figures);
}
